impl Document {
    pub(crate) fn compare_application_partition(
        &self,
        other: &Document,
        a: &ApplicationPartition,
        b: &ApplicationPartition,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_application_partition_to_ecu_partition_mapping(
        &self,
        other: &Document,
        a: &ApplicationPartitionToEcuPartitionMapping,
        b: &ApplicationPartitionToEcuPartitionMapping,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        let list_a = a.get_application_partition_refs();
        let list_b = b.get_application_partition_refs();
        if list_a.len() != list_b.len() {
            return Err(format!(
                "{path}: APPLICATION_PARTITION_REFS length mismatch"
            ));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            if x != y {
                return Err(format!(
                    "{path}.APPLICATION_PARTITION_REFS[{index}] mismatch"
                ));
            }
        }
        if a.get_ecu_partition_ref() != b.get_ecu_partition_ref() {
            return Err(format!("{path}: ECU_PARTITION_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_component_clustering(
        &self,
        other: &Document,
        a: &ComponentClustering,
        b: &ComponentClustering,
        path: &str,
    ) -> Result<(), String> {
        self.compare_mapping_constraint(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_component_separation(
        &self,
        other: &Document,
        a: &ComponentSeparation,
        b: &ComponentSeparation,
        path: &str,
    ) -> Result<(), String> {
        self.compare_mapping_constraint(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_ecu_partition(
        &self,
        other: &Document,
        a: &EcuPartition,
        b: &EcuPartition,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        if a.get_exec_in_user_mode() != b.get_exec_in_user_mode() {
            return Err(format!("{path}: EXEC_IN_USER_MODE mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_ecu_resource_estimation(
        &self,
        _other: &Document,
        a: &EcuResourceEstimation,
        b: &EcuResourceEstimation,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_j1939_controller_application(
        &self,
        other: &Document,
        a: &J1939ControllerApplication,
        b: &J1939ControllerApplication,
        path: &str,
    ) -> Result<(), String> {
        self.compare_ar_element(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_j1939_controller_application_to_j1939_nm_node_mapping(
        &self,
        _other: &Document,
        a: &J1939ControllerApplicationToJ1939NmNodeMapping,
        b: &J1939ControllerApplicationToJ1939NmNodeMapping,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_mapping_constraint(
        &self,
        _other: &Document,
        a: &MappingConstraint,
        b: &MappingConstraint,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_swc_to_application_partition_mapping(
        &self,
        other: &Document,
        a: &SwcToApplicationPartitionMapping,
        b: &SwcToApplicationPartitionMapping,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        Ok(())
    }

    pub(crate) fn compare_swc_to_ecu_mapping(
        &self,
        other: &Document,
        a: &SwcToEcuMapping,
        b: &SwcToEcuMapping,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        let list_a = a.get_component_i_refs();
        let list_b = b.get_component_i_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: COMPONENT_I_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .component_in_system_instance_refs
                .get(*x)
                .ok_or_else(|| {
                    format!("{path}.COMPONENT_I_REFS[{index}]: id not found in own arena")
                })?;
            let y = other
                .component_in_system_instance_refs
                .get(*y)
                .ok_or_else(|| {
                    format!("{path}.COMPONENT_I_REFS[{index}]: id not found in other arena")
                })?;
            self.compare_component_in_system_instance_ref(
                other,
                x,
                y,
                &format!("{path}.COMPONENT_I_REFS[{index}]"),
            )?;
        }
        if a.get_controlled_hw_element_ref() != b.get_controlled_hw_element_ref() {
            return Err(format!("{path}: CONTROLLED_HW_ELEMENT_REF mismatch"));
        }
        if a.get_ecu_instance_ref() != b.get_ecu_instance_ref() {
            return Err(format!("{path}: ECU_INSTANCE_REF mismatch"));
        }
        if a.get_processing_unit_ref() != b.get_processing_unit_ref() {
            return Err(format!("{path}: PROCESSING_UNIT_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_swc_to_impl_mapping(
        &self,
        other: &Document,
        a: &SwcToImplMapping,
        b: &SwcToImplMapping,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        self.compare_variation_point_capable(
            other,
            a.variation_point_capable(),
            b.variation_point_capable(),
            path,
        )?;
        let list_a = a.get_component_i_refs();
        let list_b = b.get_component_i_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: COMPONENT_I_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .component_in_system_instance_refs
                .get(*x)
                .ok_or_else(|| {
                    format!("{path}.COMPONENT_I_REFS[{index}]: id not found in own arena")
                })?;
            let y = other
                .component_in_system_instance_refs
                .get(*y)
                .ok_or_else(|| {
                    format!("{path}.COMPONENT_I_REFS[{index}]: id not found in other arena")
                })?;
            self.compare_component_in_system_instance_ref(
                other,
                x,
                y,
                &format!("{path}.COMPONENT_I_REFS[{index}]"),
            )?;
        }
        if a.get_component_implementation_ref() != b.get_component_implementation_ref() {
            return Err(format!("{path}: COMPONENT_IMPLEMENTATION_REF mismatch"));
        }
        Ok(())
    }
}
